<?php

declare(strict_types=1);

namespace Shared\Application\Audit;

use function Symfony\Component\String\u;

/**
 * Technical context of the request: client IP (only through trusted proxies), user agent cut to 512 characters,
 * and the request id generated by the server (an incoming X-Request-Id is ignored).
 */
final readonly class RequestContext
{
    public const int MAX_USER_AGENT = 512;

    public string $userAgent;

    private function __construct(public ?string $ip, string $userAgent, public string $requestId)
    {
        $this->userAgent = u($userAgent)->truncate(self::MAX_USER_AGENT)->toString();
    }

    public static function of(?string $ip, string $userAgent, string $requestId): self
    {
        return new self($ip, $userAgent, $requestId);
    }

    public static function cli(string $requestId): self
    {
        return new self(null, 'cli', $requestId);
    }
}
